@namespace sv_320d3576413d4c3899da17eae04fdcd9.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" @bind="CoverLetter" @bind:event="oninput"
                  class="form-control cover-letter-textarea" rows="12"
                  maxlength="@MaxLength"></textarea>
        <span class="character-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <div class="validation-summary">@validationMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private async Task HandleNext()
    {
        validationMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            validationMessage = "Please write a cover letter.";
            return;
        }

        if (CoverLetter.Length > MaxLength)
        {
            validationMessage = $"Cover letter must be {MaxLength} characters or fewer.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_320d3576413d4c3899da17eae04fdcd9.Components.Pages.Apply
@using sv_320d3576413d4c3899da17eae04fdcd9.Models

<div class="step-content">
    <h2>Review & Submit</h2>

    <section class="review-section">
        <div class="review-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <div class="review-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span class="date-range">
                    @entry.StartDate.ToString("MMM yyyy") –
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-entry">
                <strong>@r.Name</strong> (@r.Relationship)<br />
                @r.Email | @r.Phone
            </div>
        }
    </section>

    <section class="review-section">
        <div class="review-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </section>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="validation-summary">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@isSubmitting">
            @if (isSubmitting)
            {
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceForm.ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }

    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        errorMessage = null;

        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

