{"file_text": "@page "/apply"
@namespace sv_320d3576413d4c3899da17eae04fdcd9.Components.Pages.Apply
@using sv_320d3576413d4c3899da17eae04fdcd9.Models
@using sv_320d3576413d4c3899da17eae04fdcd9.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @if (submittedId.HasValue)
    {
        <div class="submission-confirmation">
            <div class="success-icon">✓</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <strong class="application-id">@submittedId.Value</strong>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@currentStep"
                       CompletedSteps="@completedSteps"
                       OnStepSelected="GoToStep" />

        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName"
                                  Email="@email"
                                  Phone="@phone"
                                  Address="@address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="@workEntries"
                                 OnNext="HandleWorkHistoryNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="@references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="@GetPersonalInfo()"
                            WorkEntries="@workEntries"
                            References="@references"
                            CoverLetter="@coverLetter"
                            OnBack="GoBack"
                            OnEditStep="GoToStep"
                            OnSubmit="HandleSubmit" />
                break;
        }
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private int? submittedId;

    // Step 1: Personal Info
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2: Work History
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { new() };

    // Step 3: References
    private List<ReferenceForm.ReferenceModel> references = new() { new(), new() };

    // Step 4: Cover Letter
    private string coverLetter = "";

    private PersonalInfo GetPersonalInfo() => new(fullName, email, phone, address);

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        CompleteAndAdvance(0);
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        CompleteAndAdvance(1);
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        CompleteAndAdvance(2);
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        CompleteAndAdvance(3);
    }

    private async Task HandleSubmit()
    {
        var workHistory = new WorkHistory(
            workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description
            )).ToList()
        );

        var refList = references.Select(r => new Reference(
            r.Name, r.Relationship, r.Email, r.Phone
        )).ToList();

        var application = new JobApplication(GetPersonalInfo(), workHistory, refList, coverLetter);
        submittedId = await ApplicationService.SubmitApplicationAsync(application);
    }

    private void CompleteAndAdvance(int step)
    {
        completedSteps.Add(step);
        currentStep = step + 1;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }
}
