toolArgs.file_text:
.application-form {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-badge {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: white;
    margin-bottom: 0.5rem;
}

.step-item.active .step-badge {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step-item.completed .step-badge {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step-item.dimmed .step-badge {
    border-color: #dee2e6;
    color: #adb5bd;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.dimmed .step-label {
    color: #adb5bd;
}

.checkmark {
    font-size: 1.1rem;
}

/* Form Elements */
.step-content h2 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    border-color: #0d6efd;
    outline: none;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.25rem;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

.btn {
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    border: none;
    font-weight: 500;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #0a58ca;
}

.btn-outline {
    background: white;
    color: #6c757d;
    border: 1px solid #ced4da;
}

.btn-outline:hover {
    background: #f8f9fa;
}

.btn-secondary {
    background: #f8f9fa;
    color: #495057;
    border: 1px solid #ced4da;
}

.btn-secondary:hover {
    background: #e9ecef;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Validation */
.validation-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

.validation-summary {
    background: #f8d7da;
    color: #842029;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
}

/* Work Entry / Reference */
.work-entry-form,
.reference-form {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4,
.reference-form h4 {
    margin: 0;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.character-count {
    display: block;
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.character-count.over-limit {
    color: #dc3545;
    font-weight: 600;
}

/* Review Step */
.review-section {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

.review-section dl {
    margin: 0;
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
}

.review-section dt {
    font-weight: 600;
    color: #6c757d;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
}

.date-range {
    font-size: 0.9rem;
    color: #6c757d;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 4px;
    max-height: 200px;
    overflow-y: auto;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.success-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #198754;
    color: white;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.application-id {
    display: block;
    font-size: 1.5rem;
    margin: 1rem 0;
    color: #0d6efd;
}

.hint {
    color: #6c757d;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

