@namespace sv_320d3576413d4c3899da17eae04fdcd9.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="OnEndDateChanged" class="form-control" disabled="@Entry.IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@Entry.IsCurrent" @onchange="HandleCurrentChanged" /> Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="OnDescriptionChanged" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private Task OnCompanyChanged(ChangeEventArgs e)
    {
        Entry.Company = e.Value?.ToString() ?? "";
        return OnChanged.InvokeAsync(Entry);
    }

    private Task OnTitleChanged(ChangeEventArgs e)
    {
        Entry.Title = e.Value?.ToString() ?? "";
        return OnChanged.InvokeAsync(Entry);
    }

    private Task OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            Entry.StartDate = date;
        return OnChanged.InvokeAsync(Entry);
    }

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        Entry.EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        return OnChanged.InvokeAsync(Entry);
    }

    private Task OnDescriptionChanged(ChangeEventArgs e)
    {
        Entry.Description = e.Value?.ToString() ?? "";
        return OnChanged.InvokeAsync(Entry);
    }

    private Task HandleCurrentChanged(ChangeEventArgs e)
    {
        Entry.IsCurrent = (bool)(e.Value ?? false);
        if (Entry.IsCurrent) Entry.EndDate = null;
        return OnChanged.InvokeAsync(Entry);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

